namespace ghidra.app.plugin.core.datamgr.actions;




using docking;
using docking.action;
using docking.action;
using docking.widgets.tree;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr.editor;
using ghidra.app.plugin.core.datamgr.tree;
using ghidra.program.model.data;
using ghidra.program.model.dtarchive;

public class CloseArchiveAction : DockingAction {

	private DataTypeManagerPlugin plugin;

	public CloseArchiveAction(DataTypeManagerPlugin plugin) : base("Close Archive", plugin.getName())
    {
		this.plugin = plugin;

		setPopupMenuData(new MenuData(new string[] { "Close Archive" }, null, "File"));

		setDescription("Closes a data type archive and removes it from the tool " +
			"(does not affect program file associations).");
		setEnabled(true);

	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (!(context is DataTypesActionContext dtac)) {
			return false;
		}

		List<GTreeNode> selectedNodes = dtac.getSelectedNodes();

		if (selectedNodes.isEmpty()) {
			return false;
		}

		foreach (GTreeNode node in selectedNodes) {
			if (!(node is FileArchiveNode) && !(node is InvalidArchiveNode) &&
				!(node is ProjectArchiveNode)) {
				return false;
			}
		}
		return true;
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		DataTypesActionContext dtac = (DataTypesActionContext) context;
		ArchiveManager archiveManager = plugin.getArchiveManager();

		List<PersistentDataTypeArchive> archives = new();
		List<GTreeNode> selectedNodes = dtac.getSelectedNodes();
		foreach (GTreeNode node in selectedNodes) {
			if (node is InvalidArchiveNode invalidNode) {
				archiveManager.closeInvalidArchive(invalidNode.getInvalidArchive());
			}
			else if (node is ArchiveNode archiveNode) {
				PersistentDataTypeArchive archive = archiveNode.getArchive();
				archives.add(archive);
			}
		}
		if (checkEditors(archives)) {
			return;
		}
		foreach (PersistentDataTypeArchive archive in archives) {
			if (!plugin.resolveModifiedArchive(archive)) {
				return;
			}
			archiveManager.closeArchive(archive);
		}
	}

	private bool checkEditors(List<PersistentDataTypeArchive> archives) {
		DataTypeEditorManager editorManager = plugin.getEditorManager();
		foreach (PersistentDataTypeArchive archive in archives) {
			DataTypeManager dtm = archive.getDataTypeManager();
			if (!editorManager.checkEditors(dtm, true)) {
				return true;
			}
		}
		return false;
	}

}
